import numpy as np


class HeteroGNN:
    """Heterogeneous GNN with type-specific transformations."""

    def __init__(self, node_types, edge_types, hidden_dim, input_dims=None):
        self.node_types = node_types
        self.edge_types = edge_types
        self.hidden_dim = hidden_dim
        self.node_weights = {}
        for nt in node_types:
            dim = input_dims.get(nt, hidden_dim) if input_dims else hidden_dim
            self.node_weights[nt] = np.random.randn(dim, hidden_dim) * np.sqrt(2.0 / (dim + hidden_dim))
        self.edge_weights = {}
        for et in edge_types:
            self.edge_weights[et] = np.random.randn(hidden_dim, hidden_dim) * np.sqrt(2.0 / (2 * hidden_dim))

    def type_specific_transform(self, X, node_type):
        return X @ self.node_weights[node_type]

    def message_passing(self, H, edge_index, edge_type):
        src, dst = edge_index
        H_msg = {}
        for node_type in self.node_types:
            msgs = np.zeros((len(H.get(node_type, [])), self.hidden_dim))
            mask = dst == node_type
            for s, d in zip(src[mask], dst[mask]):
                for st in H:
                    if s < len(H[st]):
                        msgs[d] += H[st][s] @ self.edge_weights[edge_type]
            H_msg[node_type] = msgs
        return H_msg

    def aggregate_edge_types(self, H_by_type, node_type):
        vals = [v for k, v in H_by_type.items() if node_type in str(k)]
        return np.mean(vals, axis=0) if vals else np.zeros(self.hidden_dim)

    def forward(self, H, adj_by_edge_type):
        H_t = {nt: self.type_specific_transform(H[nt], nt) for nt in self.node_types}
        H_new = {nt: np.zeros_like(H_t[nt]) for nt in self.node_types}
        for et, eidx in adj_by_edge_type.items():
            H_msg = self.message_passing(H_t, eidx, et)
            for nt in self.node_types:
                if nt in H_msg:
                    H_new[nt] += H_msg[nt]
        return {nt: np.maximum(0, H_new[nt]) for nt in self.node_types}
